local function stage(id, title, goal, chapter, icon, steps, note, chains)
 G.stages[id]={id=id,title=title,goal=goal,chapter=chapter,icon="Interface\\Icons\\"..icon,steps=steps,note=note,chains=chains or {}}
end
stage(0,"Начало путешествия","Победить Рагнароса",1,"INV_Hammer_Unique_Sulfuras",{
 {"Подготовиться к Огненным Недрам","Достигните 60 уровня. Быстрый вход через Лотоса Хранителя Портала открывает задание «Сродство с Недрами». Обычный вход расположен в Глубинах Чёрной горы.",quest=7848},
 {"Погасить семь рун","Рекомендуемый путь для своевременного прохождения — потушить руны ботом через los и u N; точная инструкция находится в «Спойлере: боты». Цепочка Герцога Гидраксиса на Квинтэссенцию воды остаётся аутентичным вариантом, но из-за репутации и недельного сброса рейда может задержать полное прохождение на 2–3 недели и дольше. Не откладывайте Огненные Недра ради этой цепочки: именно здесь добывается первая заметная эпическая экипировка.",chain=8,spoiler="runes",special="runes"},
 {"Призвать и победить Рагнароса","Победите свиту Мажордома, найдите его у места призыва Рагнароса и поговорите с ним. После победы сверяйте фазу через «Мой этап».",achievement=686},
},"Ониксия необязательна для перехода, но вики рекомендует её пройти из-за наблюдавшихся ошибок прогрессии.",{2,3,4,8})
stage(1,"После Огненных Недр","Проверить доступ в Логово Крыла Тьмы",1,"INV_Hammer_Unique_Sulfuras",{
 {"Получить допуск в Логово Крыла Тьмы","Выполните «Приказ Чернорука», чтобы пользоваться быстрым входом через сферу. Подробные шаги — в прохождении ниже.",quest=7761},
 {"Победить Ониксию при необходимости","Для её логова нужен Амулет Пламени дракона. Раскройте цепочку Альянса или Орды в прохождении ниже.",achievement=684,chains={4,3}},
},"Ранние этапы 0–2 описаны в вики укрупнённо. Фактический ответ сервера имеет приоритет.",{2,3,4,5})
stage(2,"Логово Крыла Тьмы","Победить Нефариана",1,"INV_Misc_Head_Dragon_Black",{
 {"Организовать вход в Логово Крыла Тьмы","Вход находится в верхней части Пика Чёрной горы. «Приказ Чернорука» открывает короткий путь через сферу.",quest=7761},
 {"Пройти рейд и победить Нефариана","После победы становится доступна подготовка Ан’Киража. Перед следующим рейдом проверьте свой этап.",achievement=685},
},"Не пропускайте Бритвосмерта через los: по вики это может сломать запуск Хромаггуса.",{5})
stage(3,"Врата Ан’Киража и Зул’Гуруб","Зул’Гуруб — независимый допуск; Ан’Кираж — ветка А или Б",1,"INV_Hammer_25",{
 {"Завершить 15 ресурсных заданий","Сдайте каждый первоначальный ресурсный квест своей фракции один раз. Повторы одного задания не заменяют остальные.",resource=true},
 {"Завершить «Военные действия»","Это отдельное серверное задание после 15/15. Альянс: Фельдмаршал Снегопад на маунте в Палатах Войны Стальгорна, 100 Рекомендательных жетонов Альянса. Орда: Полководец Горчук в Аллее Духов Оргриммара, 100 Рекомендательных жетонов Орды. Если уже открылась цепочка Скипетра, этот шаг выполнен.",special="war"},
 {"Ветка А — Скипетр Зыбучих песков","Полная наградная цепочка. Награды: Скипетр Зыбучих песков для удара в гонг, легендарный чёрный киражский боевой танк и звание «Повелитель скарабеев» / «Повелительница скарабеев». Репутационный участок: «Путь праведника» один раз и «Рука праведника» пять раз — шесть партий по 200, всего 1200 панцирей.",special="scepterPath",chain=10},
 {"Ветка Б — Молот Зул’Фаррака","Короткая альтернатива только для открытия врат. Добудьте Священный молот с Квиаги Хранительницы и используйте его на алтаре Джинта’Алора. Эта ветка не является продолжением Скипетра.",special="malletPath",chain=11},
 {"Ударить в гонг Скарабея","Гонг находится у врат Ан’Киража в Силитусе. Для первого удара нужны завершённые ресурсы, «Военные действия» и один из двух предметов: Скипетр или Молот.",special="gong"},
},"Выберите только одну ветку для первого удара. Удар Молотом расходует его и, по вики, навсегда закрывает награды цепочки Скипетра этому персонажу.",{10,11,12})
stage(4,"Война в Ан’Кираже","Пройти Храм Ан’Киража (40 игроков) и победить К’Туна",1,"INV_Misc_AhnQirajTrinket_02",{
 {"Войти в Ан’Кираж","После гонга доступны Руины Ан’Киража (20 игроков) и Храм Ан’Киража (40 игроков). Если врата снова закрылись, вики советует повторное нажатие гонга; предмет повторно не нужен."},
 {"Победить колоссов Аши, Зоры и Регала","ВАЖНО НА 03.10.2026: задания на Колоссов Аши, Зоры и Регала у Джонатана Богослова не сдаются даже со статусом «Выполнено» (открытый баг-репорт №473).\nУ персонажа рядом с гонгом возьмите задания на трёх колоссов Силитуса. Для боя готовьте рейд до 40 персонажей.\nКолосс Аши — улей Аши на севере, район 43, 19. Колосс Зоры — улей Зоры на западе, район 25, 55. Колосс Регала — улей Регала на юго-востоке, район 55, 88.\nГлавная опасность — «Колоссальный удар» (Colossal Smash, заклинание 26167): после пятисекундного применения он наносит урон и отбрасывает на огромное расстояние. Удар может повторяться; не рассчитывайте на точное число применений.\nПеред атакой встаньте спиной вплотную к торчащему из земли щупальцу (отростку улья) рядом с колоссом, как на примере ниже. Пусть отбрасывание упирается в отросток. Если всё же улетели, сразу возвращайтесь к боссу. На этом сервере игроку не засчитывается убийство, если в момент смерти колосса он слишком далеко.\nНа последних 2–3% здоровья выбегайте из укрытия и добивайте рядом с боссом, только если он уже не успеет завершить следующий «Колоссальный удар». После смерти колосс пропадает: пропущенный зачёт может быть уже не вернуть. Проверяйте зачёт убийств в журнале отдельно от сдачи. В нормальной цепочке после сдачи трёх заданий открывается «Хаос и разрушение», но на 03.10.2026 сдача заблокирована серверным багом. Десятичасовой таймер здесь не подтверждён.",illustration="Interface\\AddOns\\SoloProgressGuide\\Media\\ColossusKnockbackCover.tga",mapTargets={{name="Колосс Аши — район улья Аши",zone="Силитус",zoneEN="Silithus",x=43,y=19},{name="Колосс Зоры — район улья Зоры",zone="Силитус",zoneEN="Silithus",x=25,y=55},{name="Колосс Регала — район улья Регала",zone="Силитус",zoneEN="Silithus",x=55,y=88}}},
 {"Победить К’Туна","Полное руководство допускает переход сразу с этапа 4 на этап 6 после К’Туна. Проверьте ответ .ip get после победы.",achievement=687},
},"Руины Ан’Киража не обязательны. Торговцы комплектами в Крепости Кенария появляются с этапа 5. Не ждите таймер вслепую.",{})
stage(5,"Храм Ан’Киража","Победить К’Туна",1,"INV_Misc_AhnQirajTrinket_02",{
 {"Пройти Храм Ан’Киража","Цель основного маршрута — финальный босс Храма Ан’Киража (рейд на 40 игроков). Руины Ан’Киража (рейд на 20 игроков) являются дополнительной веткой."},
 {"Победить К’Туна","Победа открывает Наксрамас-60. Проверьте фазу и начинайте допуск у Серебряного Рассвета.",achievement=687},
},"История убийств и доступ к контенту учитываются отдельно.",{})
stage(6,"Наксрамас - Classic","Победить Кел’Тузада",1,"INV_Trinket_Naxxramas06",{
 {"Получить допуск","У Анджелы Досантос в Часовне Последней Надежды выполните один из трёх вариантов «Цитадели ужаса — Наксрамаса» по вашей репутации с Серебряным Рассветом. Стоимость каждого варианта указана в прохождении.",quests={9121,9122,9123}},
 {"Завершить четыре квартала","Победите Мексну, Лотхиба, Таддиуса и Четырёх всадников. Затем вернитесь к верхней платформе у входа: перед Сапфироном должны гореть четыре огонька.",serverPhase=7,serverPhaseStatus="Закрыто по прохождению рейда: серверная прогрессия"},
 {"Победить Сапфирона и Кел’Тузада","Пройдите с верхней платформы к Сапфирону, затем победите Кел’Тузада и запросите текущий этап. Классический Наксрамас находится в Восточных Чумных землях; Наксрамас-80 — отдельная версия.",serverPhase=7,serverPhaseStatus="Наксрамас пройден: серверная прогрессия"},
},"Если четыре огонька горят, но платформа не переносит к Сапфирону, руководство советует перезайти в рейд.",{6})
-- Three journey milestones; attunement quests 9121/9122/9123 are alternatives.
G.stages[6].progressBySteps=true
stage(7,"Тёмный портал","Завершить «Битва в Проломе»",1,"Spell_Arcane_PortalOrgrimmar",{
 {"Взять переходное задание","После Наксрамаса-60 отправляйтесь к Тёмному порталу в Выжженных землях и возьмите «Битва в Проломе»."},
 {"Сдать «Битва в Проломе»","Завершение открывает Запределье и получение опыта до 70 уровня.",quest=10259},
},"После перехода классические PvP-звания становятся недоступны. Щепки Атиеша перестанут падать после открытия Wrath на этапе 12.",{})
stage(8,"Каражан и первые рейды Запределья","Победить Принца Малчезара",2,"Achievement_Boss_PrinceMalchezaar_02",{
 {"Открыть героические подземелья","На 70 уровне купите репутационные ключи пяти комплексов. Дверные ключи Разрушенных залов, Аркатраца и Тёмного лабиринта открывают проходы, но не героический режим; их цепочки показаны отдельно."},
 {"Выбрать сторону в Шаттрате","Выполните «А’дал» и «Город Света», затем выберите Алдоров или Провидцев. Это понадобится для допуска в Чёрный храм."},
 {"Получить ключ Каражана","Возьмите у Альтура оба задания перед входом. Соберите фрагменты ключа, пройдите Побег из Дарнхольда и поговорите с Медивом в Чёрных топях.",quest=9837,chains={115,40}},
 {"Победить Принца Малчезара","Победа переводит на этап 9. Для следующего допуска заранее подготовьте Вороненую урну и возьмите «Дубину Кардеша» до убийства Ночной погибели и Груула.",achievement=690},
},"Груул и Магтеридон доступны сразу. Ночная погибель вызывается отдельной цепочкой после Уважения с Аметистовым оком.",{115,116,118,40,104,105,106,107,108,109,901,902,903})
stage(9,"Змеиное святилище и Крепость Бурь","Победить Кель’таса",2,"Achievement_Boss_Kael-thasSunstrider_01",{
 {"Открыть Змеиное святилище","В героическом Узилище после первого босса найдите Скар’тиса в клетке. По «Дубине Кардеша» принесите печатки Ночной погибели и Груула.",quest=10901},
 {"Получить Ключ Урагана","Пройдите «Руку Гул’дана» и «Код Проклятия», затем испытания наару: четыре героических подземелья и Магтеридон. В Аркатраце Миллхаус должен выжить.",quest=10888,chains={140,160}},
 {"Взять «Сосуды Вечности»","До убийства Леди Вайш и Кель’таса возьмите «Сосуды Вечности» у Соридорми в Пещерах Времени: оба предмета понадобятся на этапе 10.",quest=10445},
 {"Победить Кель’таса","Победите Кель’таса в Крепости Бурь, заберите его предмет для «Сосудов Вечности» и проверьте новый этап.",achievement=696},
},"В героических Разрушенных залах доберитесь до Палача примерно за 55 минут. Уже убитый без активного задания босс не заменяет квестовый предмет.",{120,140,160})
stage(10,"Хиджал и Чёрный храм","Победить Иллидана",2,"Achievement_Boss_Illidan",{
 {"Открыть Хиджал","Сдайте «Сосуды Вечности» с предметами Леди Вайш и Кель’таса.",quest=10445},
 {"Получить Медальон Карабора","Пройдите «Таблички Баа’ри» и «Обещание Акамы», затем цели у Каратресса, Олума, Ал’ара и Лютого Хлада.",quest=10949,chains={190,200}},
 {"Победить Иллидана","Войдите в Чёрный храм с Медальоном Карабора, победите Иллидана и проверьте новый этап.",achievement=697},
},"Проходите ветку Олума на этапе 10: при раннем выполнении сервер может не выдать продолжение после Каратресса.",{170,180,190,200})
stage(11,"Зул’Аман","Победить Зул’джина",2,"INV_Misc_Head_Troll_01",{
