-- Source: full-guide.txt and article-20260524192557#los; never execute these commands.
G.botInstructions="Как использовать los:\n1. Подведите бота к нужному объекту и отправьте ему в чат команду los.\n2. В ответе найдите нужный объект и его номер. Для рун Огненных Недр выбирайте только объект, название которого начинается с Rune of; не выбирайте соседний объект.\n3. Отправьте тому же боту u N, подставив номер из его ответа. Например, u 2 подходит только для объекта под номером 2 в этом списке.\n4. Проверьте результат в игре. Для следующего объекта запросите список заново."
G.spoilers={
 runes={title="тушение рун",text="Для своевременной прогрессии рекомендуется тушить семь рун ботом через los, не дожидаясь Квинтэссенции. В пронумерованном ответе выбирайте именно объект, английское название которого начинается с Rune of ..., а не соседний объект. Отправьте тому же боту u N с номером этой строки. Перед каждой следующей руной заново запросите los; после последней ожидайте объявление Мажордома.\n\nАутентичный вариант — пройти цепочку Герцога Гидраксиса и тушить руны Квинтэссенцией воды. Он рабочий, но требуемая репутация набирается медленно: недельный сброс Огненных Недр способен задержать первый полный рейд на 2–3 недели и дольше. Поэтому цепочку можно завершить позже, а первую эпическую экипировку из рейда лучше не откладывать.\n\nВ руководстве есть и другой обход: победить доступных боссов, выйти, выбрать «Обновить все подземелья» через портрет и войти снова. Это описанный вики вариант, его работу на текущей версии сервера мы не проверяли."},
 bwl={title="двери и ограничения Логова Крыла Тьмы",text="Вики разрешает как альтернативу ключу открывать дверь в Верхнюю часть Пика Чёрной горы ботом через los. При стандартном прохождении получите Печать вознесения и войдите пешком: при приближении к двери с кольцом в сумке жаровни загорятся, дверь откроется. При входе через поиск подземелий это может не сработать.\nБритвосмерта НЕ пропускайте: руководство предупреждает, что обход через los может сломать активацию Хроммагуса."},
 aq={title="Близнецы Императоры",text="Вики описывает открытие прохода в зале Близнецов Императоров ботом через los. По руководству их убийство не обязательно для доступа к финальному боссу К'Туну. Это добровольный пропуск боя, а не обычное прохождение рейда."},
 kara={title="двери Запределья и Каражана",text="Обычный путь в Каражан: пройти цепочку на хозяйский ключ. Альтернатива вики: открыть входную решётку ботом через los.\nТакже руководство описывает обход ключей дверей Разрушенных залов, Тёмного лабиринта и Аркатраца через ботов. Это не снимает другие ограничения прогрессии и требования героической сложности.\nШахматы: обычный путь - поговорить с Медивом, затем с королём своей фракции; боты в событии не участвуют. Альтернатива вики - открыть проход ботом через los и пропустить бой; для доступа к финальному боссу Шахматы, по руководству, не обязательны."},
 council={title="Совет Иллидари",text="Руководство сообщает о проблемах масштабирования здоровья Совета Иллидари в малой группе. Как обход оно предлагает открыть дверь ботом через los и пройти дальше к Иллидану. По вики убийство Совета для доступа к финальному боссу не обязательно."},
 gluth={title="Глут",text="Драться с Глутом честно с ботами, скорее всего, не выйдет: они не умеют одновременно держать позиции и забирать агро у пробегающих зомби-закусок. Проще всего сразу пробежать к выходной двери из комнаты Глута и открыть её через los.\n\nДальше есть два варианта. Первый — попробовать убить Глута: поставьте одного танка-паладина в дверях, а второго танка — ближе к двери Таддиуса. Даже с такой расстановкой бой остаётся довольно сложным.\n\nВторой вариант — пропустить Глута. Вайпнитесь перед дверью Таддиуса, дождитесь, пока Глут успокоится, и воскресните. В группе заранее должен быть бот с умением воскрешать. После вайпа через UnBot отпустите дух всем ботам и призовите их к себе. Затем можно идти к Таддиусу: Глут для прохождения не обязателен.\n\nНа Таддиусе главное одновременно убить обоих аддов. Контролируйте входящий урон, держите их примерно на одном уровне здоровья и добейте одновременно."},
}
G.stageSpoilers={[2]="bwl",[4]="aq",[5]="aq",[6]="gluth",[8]="kara",[10]="council"}

-- Contextual guide notes paraphrased from progression guide and FAQ; not completion requirements.
G.guideNotes={
 [0]={{"Подготовка Classic","Предел уровня - 60. Руководство указывает штраф 40% к наносимому урону и получаемому лечению. Допуски можно готовить во время прокачки. Ониксия и Огненные Недра доступны параллельно; переход проверяйте по ответу сервера, а не по уровню персонажа."},{"Ониксия: амулет и Рексар","Цепочка Альянса начинается с 48 уровня, Орды - с 55. Амулет Пламени дракона должен быть у каждого входящего: в сумке или на шее. На Classic в задании «Герой Орды» вместо указанного Рокаро ищите Рексара: он патрулирует дорогу от Когтистых гор через Пустоши до Фераласа."},{"Если Ониксия открывается не в той версии","Если попали к Ониксии-80, руководство предлагает выйти и войти снова. Другой вариант - сменить сложность рейда, находясь снаружи и в группе. Если группа с ботами не входит, войдите без группы и призовите ботов уже внутри. Это рекомендации вики по ошибкам сервера, не гарантированное исправление."},{"Глубины Чёрной горы: ключ и быстрый вход в Недра","Вводное задание быстрого входа в Недра доступен с 55 уровня. Стандартный вход находится внутри Глубин Чёрной горы. Для запертых механизмов Глубин Чёрной горы нужен ключ из «Наследия Черного железа»: Франклорн Искусник стоит в гробнице на цепях в Чёрной горе, вне подземелья. Разговаривать с ним нужно в состоянии духа."}},
 [1]={{"Что подготовить перед Логовом Крыла Тьмы","Ониксия - дополнительная ветка; её амулет не заменяет допуск в Логово Крыла Тьмы. Быстрый вход в Логово Крыла Тьмы открывается цепочкой с 55 уровня. Обычный путь и заключительный шаг допуска проходят через верхнюю часть Пика Чёрной горы. Подробные цепочки доступны ниже."}},
 [2]={{"Верхняя часть Пика Чёрной горы: Печать вознесения","Цепочка кольца доступна с 57 уровня. Потребуются самоцветы с трёх боссов. Если квестодатель не разговаривает, добудьте Простую печать Вознесения с мобов подземелья и подойдите ближе. С готовым кольцом в сумке подойдите к двери: жаровни загораются, дверь открывается. Входите пешком; через поиск подземелий это может не сработать."},{"Бритвосмерт и Хроммагус: если бой не запускается","Охотнику или чернокнижнику, который не может использовать сферу Бритвосмерта, Раздел частых вопросов советует отозвать питомца. Хроммагус запускается рычагом у стены напротив входа. Если отсутствуют и решётка, и рычаг, выйдите и обновите подземелье; Раздел частых вопросов связывает проблему с обходом Бритвосмерта или некорректным восстановлением после гибели рейда."},{"Хроммагус и помощь ботов","От «Искажения времени» прячьтесь всем рейдом за стену или колонну. По вики боты сами снимают «Чернокнижие: бронзовое» без Песка времени, обезвреживают ловушки в комнате подавления и автоматически получают эффект Плаща из чешуи Ониксии. Для игрока необходимость плаща зависит от получаемого урона; не считайте поведение ботов своим баффом."}},
 [3]={{"Почему не дают «Военные действия»","Нужны все 15 разных первоначальных заданий с жёлтым восклицательным знаком, каждое хотя бы один раз. Повторяемые сдачи не заменяют пропущенный вид. Альянс сдаёт ресурсы в Палатах Войны Стальгорна, Орда - в Аллее Духов Оргриммара. Затем у главнокомандующего в центре сдайте 100 наградных печатей. Это отдельный квест прогресс-модуля."},{"Перед выбором Скипетра или Молота","Полная цепочка открывается после «Военных действий». Скипетр даёт право на награды цепочки: чёрный киражский танк и звание. По руководству удар Молотом навсегда закрывает эти награды персонажу и уничтожает Молот. Оба пути требуют предварительной сдачи ресурсов. Сохранённая отметка аддона сама гонг не открывает."},{"Зул’Гуруб: дополнительная цепочка","Полная цепочка доступна с этапа 3; раньше она останавливается после «Бога Хаккара». Порядок: «Духи крикунов», «Пророчество Мошару», «Древнее яйцо», «Бог Хаккар», «Утраченные таблички Мошару», «Последние таблички», «Сопротивление Йекинье», «Длань Растахана». Зул’Гуруб не обязателен для перехода."}},
 [4]={{"Колоссы и переход после гонга","Три цели находятся в разных ульях Силитуса: Колосс Аши — север, улей Аши (примерно 43, 19); Колосс Зоры — запад, улей Зоры (примерно 25, 55); Колосс Регала — юго-восток, улей Регала (примерно 55, 88). Метки обозначают районы поиска, а не подтверждённые точки появления на этом сервере. Задания выдаёт персонаж у гонга; после убийства и сдачи всех трёх открывается «Хаос и разрушение». Колоссы не масштабируются и рассчитаны на рейд до 40 персонажей. «Колоссальный удар» (Colossal Smash, 26167) сильно отбрасывает: перед боем встаньте спиной к выступающему щупальцу улья. По наблюдению игрока на этом сервере убийство не засчитывается, если в момент смерти колосса игрок находится слишком далеко; после отбрасывания возвращайтесь к боссу до добивания. По состоянию на 03.10.2026 выполненные задания на колоссов не сдаются у Джонатана Богослова (открытый баг-репорт №473). Зачёт убийства и возможность сдачи — разные вещи; статус «Выполнено» сейчас не завершает эту цепочку. Старое сообщение руководства об исправлении от 20.07.2026 не подтверждается текущей проверкой. По тому же руководству можно победить К’Туна уже на этапе 4 и перейти сразу к этапу 6."},{"Врата снова закрылись","Раздел частых вопросов советует повторно ударить в гонг: для повторного открытия предмет не нужен. Если реакции нет, подождите примерно минуту. Не рассчитывайте только на десятичасовой таймер: источники по работе этой фазы расходятся. После победы над К’Туном запросите свой этап."},{"Обмен комплектов Руин Ан’Киража","Персонажи, обменивающие предметы комплектов в Крепости Кенария, появляются с этапа 5 и далее. Отсутствие этих персонажей на этапе 4 не означает, что вам нужно заново собирать ресурсы."}},
 [5]={{"Быстрые перемещения по Храму Ан’Киража","После убийства Императоров Персонажи в начале рейда открывают телепорт в их комнату. Ищите этих персонажей в левой комнате после Пророка Скерама. После Оуро у них появляется перемещение к комнате К’Туна. Прохождение Руины Ан’Киража (20 игроков) для перехода не требуется."}},
 [6]={{"Вход в Наксрамас-60 и комплект третьего тира","Допуск выдаёт Анджела Досантос в Часовне Последней Надежды; стоимость зависит от Серебряного Рассвета. Для обмена комплектов третьего тира у представителей вашего класса сначала выполните «Отголоски войны». Вход: кристалл в первом зиккурате справа от дороги к Стратхольму после входа в Проклятый лес, Восточные Чумные земли."},{"Попали в Наксрамас-80 или не можете выйти","Раздел частых вопросов советует повторный вход либо смену сложности снаружи, находясь в группе. В классической версии обычный портал наружу может не работать: заранее подготовьте Камень возвращения. Руководство также упоминает выход через смерть или перезаход в группе."},{"Четыре квартала и платформа Сапфирона","Нужны Мексна, Лотхиб, Таддиус и Четыре всадника. После них используйте появившиеся телепорты ко входу. Должны гореть четыре огонька вокруг верхней платформы. Если они горят, а переноса нет, перезайдите в рейд. Лут Всадников находится в сундуке у дальней стены. По руководству после зачистки вход может вести прямо к Сапфирону до обновления сохранения рейда."},{"Готик: бой сбрасывается","Оставьте персонажей по обе стороны арены: Раздел частых вопросов сообщает о сбросе боя, если одна половина пуста. Это обычное распределение рейда, не обход. При зависшем боссе вне боя Раздел частых вопросов предлагает вывести всех персонажей, включая ботов, и обновить подземелье."}},
 [7]={{"Что меняется после «Битвы в Проломе»","Квест появляется у Тёмного портала в Выжженных землях. Его сдача открывает Запределье и опыт до 70 уровня. Классическая система PvP-званий после перехода становится недоступной; с этапа 8 Дом офицеров открыт всем."}},
 [8]={{"Подготовка The Burning Crusade: уровни и героические ключи","Предел уровня - 70; урон и получаемое лечение снижены на 20%. Для подземелий в героическом режиме нужны репутационные ключи пяти комплексов: Цитадель Адского Пламени, Резервуар Кривого Клыка, Аукиндон, Крепость Бурь и Пещеры Времени. Репутацию набирают заданиями и обычными подземельями. Выбрать героическую сложность можно с 70 уровня, в группе и вне подземелья."},{"Дверные ключи и Пещеры Времени","Ключ Разрушенных залов - цепочка с 68 уровня; Аркатраца - с 67; ключ Тёмного лабиринта падает с последнего босса Сетеккских залов. Они не заменяют ключи героической сложности. Для Пещер Времени сначала пройдите вводную цепочку с 66 уровня, затем Побег из Дарнхольда и его продолжение для доступа к Чёрным топям."},{"Выбор Алдоров или Провидцев","С 65 уровня в Шаттрате возьмите «А’дал» у Измождённого ветерана возле северного моста, затем «Город Света» у Кадгара. После экскурсии выберите сторону. Без этого выбора начало допуска в Чёрный храм недоступно. Выбор определяет квестодателя, но обе стороны позволяют пройти прогрессию."},{"Ночная погибель: подготовьте следующий этап","Альтур перед Каражаном даёт два стартовых задания; оба входят в допуск с 70 уровня, проходимый в обычных подземельях. Для Ночной погибели нужна отдельная цепочка после Уважения с Аметистовым оком, включая героические Разрушенные и Сетеккские залы. Полученную Вороненую урну держите в сумке, но нажимайте урну на полу Террасы Мастера. Предмет с босса нужен для допуска в Змеиное святилище на следующем этапе: не расходуйте убийство до получения нужного задания."},{"Магтеридон: обычная работа ботов","Для ротации Кубов Мантикрона возьмите минимум пять ботов. Чаротворцев распределите по меткам: квадрат, звезда, круг, ромб, треугольник. Если боты не выставили метки, расставьте их вручную перед боем. Груул и Магтеридон доступны сразу, но их предметы понадобятся для следующих допусков."}},
 [9]={{"Змеиное святилище: допуск и мост к Вайш","Скар’тис Еретик находится в клетке слева после первого босса героического Узилища: спрыгните в воду и выберитесь. Для «Дубины Кардеша» нужны предметы Ночной погибели и Груула. Для моста к Вайш победите остальных боссов, включая Скрытня из глубин, затем нажмите панель на краю платформы. Для вызова Скрытня достаточно удочки; высокий навык рыбалки не нужен."},{"Вайш: сферы и распределение добычи","Перед фазой со сферами выберите «Добыча: каждый за себя» и проверьте стратегию loot у ботов: иначе сферы с чумных элементалей могут оказаться недоступны. После этой фазы верните прежнее распределение до смерти босса. Вайш нужна для Сосудов Вечности на следующем этапе, хотя переход здесь запускает Кель’тас."},{"Ключ Урагана: четыре особых условия","После «Руки Гул’дана» и «Кода Проклятия» дождитесь письма Кадгара и продолжите цепочку. В героических Разрушенных залах убейте Палача примерно за 55 минут и возьмите топор; в Паровом подземелье - трезубец Калитреша; в Тёмном лабиринте - сущность Бормотуна; в Аркатраце победите Скайрисса, сохранив жизнь Миллхаусу. Затем требуется Магтеридон. Подробные задания доступны в цепочке допуска."},{"Кель’тас: сохраните возможность получить добычу","Не добивайте Кель’таса в воздухе во время смены фаз: добыча может стать недоступной. До боя проверьте задания на его предметы."}},
 [10]={{"Порядок рейдов без лишнего ожидания обновления рейдов","Сначала доведите допуск Чёрного храма до задания, требующего Ал’ара. Тогда поход в Крепость Бурь можно совместить со сбором предмета Кель’таса для Сосудов Вечности. В Змеином святилище нужны Каратресс для продолжения цепочки и Вайш для Сосудов. Хиджал целиком проходить для перехода не требуется, но Лютый Хлад нужен для Чёрного храма."},{"Олум не даёт продолжение","После «Обещания Акамы» победите Каратресса: из клетки выйдет Провидец Олум с «Тайной под угрозой». Выполняйте этот шаг на этапе 10: при раннем прохождении сервер может не выдать продолжение. Проверьте журнал и текущий этап."},{"Медальон, телепорты и добыча Совета","Медальон Карабора позволяет войти в Чёрный храм. Продолжение цепочки через Пеплоустов, Тень Акамы и Иллидана награждает Благословленным медальоном с телепортом к храму. После Супремуса Дух Олума у выхода из первого тоннеля переносит в Святилище Теней. После Совета появляется перенос к его комнате у Олума и Духа Адало. Обыщите каждого Консула: добыча раздельная."}},
 [11]={{"Переход из Зул’Амана","Отдельный допуск не нужен. Победите Зул’джина и запросите текущий этап."}},
 [12]={{"Кель’Данас и Терраса Магистров","Остров Кель’Данас открыт целиком. Для героической Террасы Магистров нужна короткая цепочка из библиотеки допусков, но для перехода она не требуется. Плато Солнечного колодца доступно сразу."},{"Перед Кил’джеденом: Атиеш и переход в Wrath","Победа открывает опыт до 80, Нордскол и создание рыцаря смерти на аккаунте. После перехода Наксрамас становится версией для 80 уровня, где щепки Атиеша не падают. Если собираете посох, завершите нужную часть Classic заранее."}},
 [13]={{"Начало Wrath и рыцари смерти","Предел уровня - 80; штрафов Classic/The Burning Crusade к урону и получаемому лечению больше нет. Рыцари смерти начинают на этапе 13 даже с 55 уровня; предыдущая прогрессия им не обязательна. В Нордскол можно отправляться с 68 уровня. Часть героических подземелий требует подходящей экипировки."},{"Дополнительные рейды: Малигос и Сартарион","Для Ока Вечности хотя бы одному участнику нужен Ключ к Радужному Средоточию из задания по предмету Сапфирона в Наксрамасе-80. В библиотеке есть варианты на 10 и 25. Обсидиановое святилище доступно сразу. Малигос и Сартарион не обязательны для перехода - нужен Кел’Тузад."}},
 [14]={{"Условия перехода","Ульдуар доступен без отдельного допуска. Победите Йогг-Сарона и запросите текущий этап. Алгалон для перехода не нужен."}},
 [15]={{"Серебряный Турнир и два разных подземелья","Открываются Турнир, его задания и персонажи, Испытание чемпиона и Испытание крестоносца. Чемпион - дополнительное подземелье; Крестоносец - нужный рейд. Отдельный допуск не нужен: для перехода победите Ануб’арака в рейде."}},
 [16]={{"Ледяные залы: отдельная цепочка с 78 уровня","Возьмите фракционный вариант «В ледяную цитадель» и пройдите Кузню Душ. Продолжение открывает Яму Сарона, затем Залы Отражений и задание «Ледяная Скорбь». Это дополнительная ветка: она не является условием входа в рейд Цитадель Ледяной Короны или перехода."},{"Какой Король-лич засчитывается","Победите Короля-лича в рейде на 25 игроков. Залы Отражений и рейд на 10 эту цель не заменяют. После победы запросите текущий этап."}},
 [17]={{"Завершение пути","Рубиновое святилище доступно сразу. Цель - Халион; наличие этапа 17 означает доступ к нему. После победы запросите этап, чтобы отделить открытый рейд от завершённого маршрута."}},
 [18]={{"Дополнительные цели после завершения","Открытие всего контента не подтверждает сдачу каждой побочной цепочки. Проверяйте задания отдельно в библиотеке. Не рассчитывайте на автоматическое восстановление упущенных наград Скипетра или старого Наксрамаса: ограничения описаны в соответствующих этапах."}},
}

